run_command:
$ErrorActionPreference='Stop'
$PSNativeCommandUseErrorActionPreference=$false
$registration='a4a9ec4cdd85948af120d3f52f61c8179d6845c7'
if((git rev-parse HEAD).Trim() -ne $registration){throw 'Registered HEAD drifted'}
if(Test-Path -LiteralPath 'outputs/msb_native_supervision_v3'){throw 'Native output already consumed'}
$entry='.superpowers/sdd/2026-10-25-msb-native-supervision-v3-execution'
if(Test-Path -LiteralPath $entry){throw 'Entry directory already exists; no retry'}
$p=Get-Content -LiteralPath 'docs/experiment_protocols/msb_native_supervision_v3.json' -Raw|ConvertFrom-Json
if($p.status -ne 'APPROVED_NATIVE_ONLY' -or $p.approval_call_id -ne 'call_d7ead69a9778437890a84a9c099e586a' -or $p.approval_answer -cne '批准一次固定协议原生验收（推荐）'){throw 'Approval mismatch'}
foreach($v in $p.source_sha256.PSObject.Properties){if((Get-FileHash -LiteralPath $v.Name -Algorithm SHA256).Hash.ToLowerInvariant() -ne $v.Value){throw "Source drift $($v.Name)"}}
New-Item -ItemType Directory -Path $entry | Out-Null
$savedBytecode=$env:PYTHONDONTWRITEBYTECODE
$savedUtf8=$env:PYTHONUTF8
$env:PYTHONDONTWRITEBYTECODE='1'
$env:PYTHONUTF8='1'
$code=$null
try {
& 'D:\成信工科研\人工智能选矿\.venv-training\Scripts\python.exe' '.\scripts\check_msb_native_supervision.py' --root 'D:\成信工科研\人工智能选矿\.worktrees\theory-aware-report' --protocol 'D:\成信工科研\人工智能选矿\.worktrees\theory-aware-report\docs\experiment_protocols\msb_native_supervision_v3.json' --execute-native --approval-call-id 'call_d7ead69a9778437890a84a9c099e586a' --approval-answer '批准一次固定协议原生验收（推荐）' --registration-commit $registration 1> "$entry/collector_stdout.log" 2> "$entry/collector_stderr.log"
$code=$LASTEXITCODE
} finally {
$env:PYTHONDONTWRITEBYTECODE=$savedBytecode
$env:PYTHONUTF8=$savedUtf8
}
Write-Output ("COLLECTOR_EXIT_CODE="+$code)
if($null -eq $code){throw 'Collector exit code unavailable; stop without retry'}
exit $code
